-- Vibes editable posts and conversational replies; preserve authorship and audit dates.
BEGIN;
ALTER TABLE vibes_posts DROP CONSTRAINT IF EXISTS vibes_posts_body_check;
ALTER TABLE vibes_comments DROP CONSTRAINT IF EXISTS vibes_comments_body_check;
-- Existing inline checks may have autogenerated names; drop by catalog to avoid duplicates.
DO $$ DECLARE r record; BEGIN
 FOR r IN SELECT conname FROM pg_constraint WHERE conrelid='public.vibes_posts'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%char_length(body)%'
 LOOP EXECUTE format('ALTER TABLE vibes_posts DROP CONSTRAINT %I',r.conname); END LOOP;
 FOR r IN SELECT conname FROM pg_constraint WHERE conrelid='public.vibes_comments'::regclass AND contype='c' AND pg_get_constraintdef(oid) ILIKE '%char_length%body%'
 LOOP EXECUTE format('ALTER TABLE vibes_comments DROP CONSTRAINT %I',r.conname); END LOOP;
END $$;
ALTER TABLE vibes_posts ADD CONSTRAINT vibes_posts_body_length_check CHECK(char_length(body)<=10000);
ALTER TABLE vibes_comments ADD CONSTRAINT vibes_comments_body_length_check CHECK(char_length(btrim(body)) BETWEEN 1 AND 10000);
ALTER TABLE vibes_posts ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
ALTER TABLE vibes_comments ADD COLUMN IF NOT EXISTS edited_at TIMESTAMPTZ;
COMMIT;